<script setup lang="ts">
import { reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, type FormInstance, type FormRules } from 'element-plus'
import { useAuthStore } from '@/stores/auth'

const auth = useAuthStore(), router = useRouter(), route = useRoute()
const formRef = ref<FormInstance>()
const form = reactive({ username: '', password: '', remember: true })
const rules: FormRules = { username: [{ required: true, message: '请输入用户名', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }] }
async function submit(instance?: FormInstance) { if (!await instance?.validate().catch(() => false)) return; try { await auth.login(form); ElMessage.success('登录成功'); router.replace(String(route.query.redirect || '/dashboard')) } catch { ElMessage.error('账号或密码错误') } }
</script>
<template><main class="login-page"><section class="login-intro"><div class="intro-content"><span class="logo">冯</span><h1>让家族记忆，代代相传</h1><p>安全、清晰地管理族谱成员、亲属关系与珍贵史料。</p><ul><li>完整谱系与四种可视化图谱</li><li>协作审核与细粒度权限</li><li>史料 OCR、故事与永久备份</li></ul></div></section><section class="login-form-wrap"><div class="login-box"><p class="eyebrow">欢迎使用</p><h2>登录冯氏</h2><p class="muted">请输入您的家谱系统账号</p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" size="large" @keyup.enter="submit(formRef)"><el-form-item label="账号" prop="username"><el-input v-model="form.username" autocomplete="username" placeholder="请输入用户名" /></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" autocomplete="current-password" show-password placeholder="请输入密码" /></el-form-item><div class="login-options"><el-checkbox v-model="form.remember">保持登录</el-checkbox><el-link type="primary">忘记密码？</el-link></div><el-button type="primary" class="login-submit" :loading="auth.loading" @click="submit(formRef)">登 录</el-button></el-form><p class="login-help">无法登录？请联系家谱管理员重置账号。</p></div></section></main></template><style scoped>.login-page{min-height:100vh;display:grid;grid-template-columns:1.1fr 1fr;background:white}.login-intro{position:relative;display:grid;place-items:center;padding:60px;background:linear-gradient(145deg,#111827,#1e3a8a);color:white;overflow:hidden}.login-intro:after{content:"谱";position:absolute;font-size:520px;color:#fff;opacity:.025;right:-80px;bottom:-180px}.intro-content{max-width:520px;position:relative;z-index:1}.logo{display:grid;place-items:center;width:54px;height:54px;background:#2563eb;border-radius:14px;font-size:28px;font-weight:bold}.intro-content h1{font-size:42px;margin:36px 0 14px}.intro-content>p{color:#cbd5e1;font-size:18px;line-height:1.8}.intro-content ul{list-style:none;padding:0;margin-top:40px}.intro-content li{margin:18px 0;color:#e2e8f0}.intro-content li:before{content:"✓";display:inline-grid;place-items:center;width:22px;height:22px;margin-right:12px;border-radius:50%;background:#0f766e}.login-form-wrap{display:grid;place-items:center;padding:40px}.login-box{width:min(400px,100%)}.eyebrow{color:#2563eb;font-weight:700}.login-box h2{font-size:32px;margin:8px 0}.login-box>.muted{margin-bottom:32px}.login-options{display:flex;justify-content:space-between;margin:-4px 0 22px}.login-submit{width:100%}.login-help{text-align:center;color:#94a3b8;font-size:13px;margin-top:28px}@media(max-width:760px){.login-page{grid-template-columns:1fr}.login-intro{display:none}.login-form-wrap{padding:28px}}</style>
